# compile patterns per class: list of (regex, weight)
PAT = {}
for cls, words in KW.items():
    items = words.split()
    pats = []
    for w in items:
        w = w.strip('"').lower()
        if not w: continue
        pat = r"\b" + re.escape(w).replace(r"\ ", r"\s+") + r"\b"
        pats.append(re.compile(pat))
    PAT[cls] = pats

def classify(title, desc):
    t = (title or "").lower()
    d = (desc or "").lower()
    scores = {}
    for cls, pats in PAT.items():
        s = 0
        for p in pats:
            if p.search(t):
                s += 3
            if p.search(d):
                s += 1
        scores[cls] = s
    best = max(scores, key=lambda c: (scores[c], c))
    if scores[best] == 0:
        return "Unknown", scores
    return best, scores

cls_count = Counter()
world_by_region = Counter()
all_by_region = Counter()
unknowns = []
for a in arts:
    c, sc = classify(a.get("title"), a.get("description"))
    reg = region_of[a["article_id"]]
    cls_count[c] += 1
    all_by_region[reg] += 1
    if c == "World":
        world_by_region[reg] += 1
    if c == "Unknown":
        unknowns.append((a["article_id"], a.get("title")))

print("Total articles:", len(arts))
print("Class distribution:", dict(cls_count))
print()
print("World-category counts by region:")
for reg, n in world_by_region.most_common():
    print(f"  {reg}: {n}")
print()
print("All 2015 articles by region:", dict(all_by_region))
print("Unknown examples:", unknowns[:15])
print("n unknown:", len(unknowns))
